var q = QueryRetriever;
var raw = globalThis["OsmLandmarksRetriever"];
if (raw === undefined) {
  return {
    ok: false,
    err: "Keine Friedhof-/Kirchen-Daten (Dienst nicht erreichbar).",
    center: { lat: parseFloat(q.lat), lng: parseFloat(q.lng) },
    radiusM: 0,
    spots: []
  };
}
if (typeof raw === "string" && raw.indexOf("Error") === 0) {
  return {
    ok: false,
    err: raw,
    center: { lat: parseFloat(q.lat), lng: parseFloat(q.lng) },
    radiusM: 0,
    spots: []
  };
}
var els = raw.elements || [];
var spots = [];
for (var i = 0; i < els.length; i++) {
  var e = els[i];
  var tags = e.tags || {};
  var kind = "church";
  if (tags.amenity === "grave_yard" || tags.landuse === "cemetery") {
    kind = "cemetery";
  } else if (tags.amenity === "place_of_worship") {
    kind = "church";
  }
  var label = e.name;
  if (!label) {
    label = kind === "cemetery" ? "Friedhof" : "Kirche";
  }
  spots.push({
    lat: e.lat,
    lng: e.lon,
    name: label,
    kind: kind
  });
}
return {
  ok: true,
  center: raw.center,
  radiusM: raw.radiusM,
  spots: spots
};

